ALTER TABLE players ADD COLUMN reg_ip TEXT;
ALTER TABLE players ADD COLUMN last_ip TEXT;
ALTER TABLE players ADD COLUMN last_seen INTEGER;
CREATE UNIQUE INDEX IF NOT EXISTS players_phone ON players (phone);
CREATE TABLE IF NOT EXISTS sponsors (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, url TEXT NOT NULL, kind TEXT NOT NULL, image_key TEXT, logo_key TEXT, active INTEGER NOT NULL DEFAULT 1, start_day TEXT, end_day TEXT, sort INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS prizes (id INTEGER PRIMARY KEY AUTOINCREMENT, place TEXT NOT NULL, name TEXT NOT NULL, value TEXT, sponsor TEXT, image_key TEXT, sort INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media (key TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, size INTEGER NOT NULL, uploaded_at INTEGER NOT NULL);
